  ["data.otservbr.global.npc.a.dragon.mother.L58.203"] = "Saludos humanos! Considérate afortunado, necesito {help}.",
  ["data.otservbr.global.npc.a.dragon.mother.L62.204"] = "Grrr.",
  ["data.otservbr.global.npc.a.dragon.mother.L65.205"] = "Me has hecho un favor y el conocimiento que buscas será tuyo. Derretí el hielo por ti, puedes pasar ahora.",
  ["data.otservbr.global.npc.a.drillworm.L56.1124"] = "¡Pssst! ¡Mantenlo bajo! <te da un informe elaborado sobre la actividad de los monstruos>",
