  ["data.otservbr.global.npc.a.fading.memory.L53.1295"] = "Oh...",
  ["data.otservbr.global.npc.a.fluffy.squirrel.L71.1052"] = "¿Chhchh?",
  ["data.otservbr.global.npc.a.fluffy.squirrel.L72.1053"] = "Ch...",
  ["data.otservbr.global.npc.a.fluffy.squirrel.L73.1054"] = "Ch...",
  ["data.otservbr.global.npc.a.fluffy.squirrel.L74.1055"] = "Chchch. Chh! <no estás seguro, pero parece que la ardilla quiere cambiar tus valiosas bellotas por piedras inútiles que encontró y consideró no comestibles>",
  ["data.otservbr.global.npc.a.frog.L57.1456"] = "*suspiro* Otro aventurero tonto más.",
  ["data.otservbr.global.npc.a.frog.L58.1457"] = "¡Sí, adiós y no vuelvas!",
  ["data.otservbr.global.npc.a.frog.L59.1458"] = "¡Ja! Ese idiota finalmente se fue.",
  ["data.otservbr.global.npc.a.ghostly.sage.L60.1103"] = "Ah, siento que un mortal vuelve a caminar por estos antiguos pasillos. Perdóname, apenas te noto. Estoy tan perdido en mis pensamientos.",
  ["data.otservbr.global.npc.a.ghostly.sage.L61.1104"] = "Adiós.",
  ["data.otservbr.global.npc.a.ghostly.sage.L62.1105"] = "Adiós entonces.",
  ["data.otservbr.global.npc.a.ghostly.woman.L62.1178"] = "Te siento. Escucho tus pensamientos. Estás... vivo.",
  ["data.otservbr.global.npc.a.ghostly.woman.L63.1179"] = "Solo... tan solo. Tan frío.",
  ["data.otservbr.global.npc.a.ghostly.woman.L64.1180"] = "Solo... tan solo. Tan frío.",
