  ["data.otservbr.global.npc.a.majestic.warwolf.L83.37"] = "Interesante. Un humano que puede hablar el idioma de los lobos.",
  ["data.otservbr.global.npc.a.majestic.warwolf.L84.38"] = "YOOOOUHHOOOUU!",
  ["data.otservbr.global.npc.a.majestic.warwolf.L85.39"] = "YOOOOUHHOOOUU!",
  ["data.otservbr.global.npc.a.nightmare.scion.L56.996"] = "¡Pssst! ¡Mantenlo bajo! <te da un informe elaborado sobre la actividad de los monstruos>",
  ["data.otservbr.global.npc.a.nightmare.scion.L65.997"] = "¡Pssst! ¡Mantenlo bajo! <te da un informe elaborado sobre la actividad de los monstruos>",
  ["data.otservbr.global.npc.a.nightmare.scion.L72.998"] = "¡Pssst! ¡Mantenlo bajo! <te da un informe elaborado sobre la actividad de los monstruos>",
  ["data.otservbr.global.npc.a.prisoner.L138.261"] = "¡Esperar! ¡No te vayas! Quiero contarles sobre mis números surrealistas.",
  ["data.otservbr.global.npc.a.prisoner.L139.262"] = "¡Adiós! No te olvides de los secretos de las matemáticas.",
  ["data.otservbr.global.npc.a.prisoner.L140.263"] = "¿Eh? ¿Qué? ¡Puedo ver! ¡Guau! Un no mino. ¿Te {capture} a ti también?",
  ["data.otservbr.global.npc.a.restless.soul.L53.44"] = "Uhhhh...",
  ["data.otservbr.global.npc.a.restless.soul.L56.45"] = "¡Ahhh! ¡Por fin alguien que puede escuchar mi {story}!",
  ["data.otservbr.global.npc.a.sleeping.dragon.L51.150"] = "ZzzzZzzZz...chrrr...",
  ["data.otservbr.global.npc.a.sleeping.dragon.L53.151"] = "Saludos, {wayfarer}.",
  ["data.otservbr.global.npc.a.strange.chalice.L117.1623"] = "¿Hola? ¿Qué quieres decir con 'hi'? ¿No ves que soy un...? Tengo que bajar la voz. ¿Se te ocurrió que este 'chalice' no quiere que lo molesten? ¡Déjame en paz!",
  ["data.otservbr.global.npc.a.swan.L95.88"] = "Te saludo, ser mortal.",
  ["data.otservbr.global.npc.a.sweaty.cyclops.L227.68"] = "¡Hmmmm! Bienvenido pequeño |PLAYERNAME|.",
  ["data.otservbr.global.npc.a.sweaty.cyclops.L228.69"] = "Adiós pequeña.",
  ["data.otservbr.global.npc.a.vulcongra.L56.934"] = "¡Pssst! ¡Mantenlo bajo! <te da un informe elaborado sobre la actividad de los monstruos>",
  ["data.otservbr.global.npc.a.vulcongra.L65.935"] = "¡Pssst! ¡Mantenlo bajo! <te da un informe elaborado sobre la actividad de los monstruos>",
  ["data.otservbr.global.npc.a.vulcongra.L72.936"] = "¡Pssst! ¡Mantenlo bajo! <te da un informe elaborado sobre la actividad de los monstruos>",
  ["data.otservbr.global.npc.a.weakened.forest.fury.L122.711"] = "Te saludo, humano. Este es un momento de angustia, más que nunca necesitamos guardianes que nos protejan a nosotros y a nuestro mundo.",
  ["data.otservbr.global.npc.a.wrinkled.bonelord.L80.1421"] = "¿Qué es esto? Una entidad con problemas ópticos llamada |PLAYERNAME|. ¡Qué fascinante!",
  ["data.otservbr.global.npc.a.wrinkled.bonelord.L81.1422"] = "Espera ahí mismo. Te comeré después de escribir lo que descubrí.",
  ["data.otservbr.global.npc.a.wrinkled.bonelord.L82.1423"] = "Espera ahí mismo. Te comeré después de escribir lo que descubrí.",
  ["data.otservbr.global.npc.a.wyrm.L56.1560"] = "¡Pssst! ¡Mantenlo bajo! <te da un informe elaborado sobre la actividad de los monstruos>",
  ["data.otservbr.global.npc.a.wyrm.L65.1561"] = "¡Pssst! ¡Mantenlo bajo! <te da un informe elaborado sobre la actividad de los monstruos>",
  ["data.otservbr.global.npc.a.wyrm.L72.1562"] = "¡Pssst! ¡Mantenlo bajo! <te da un informe elaborado sobre la actividad de los monstruos>",
  ["data.otservbr.global.npc.ahmet.L182.407"] = "Sea llorado peregrino en carne. Vendo mercadería general. Sólo pídeme un {trade}.",
  ["data.otservbr.global.npc.ajax.L58.355"] = "Has vuelto. Sabes, tienes razón. El hermano tiene razón. El puño no siempre es bueno. ¡Dile eso!",
  ["data.otservbr.global.npc.ajax.L61.356"] = "¿Qué haces en mi lugar?",
  ["data.otservbr.global.npc.al.dee.L166.596"] = "Bye, bye.",
  ["data.otservbr.global.npc.al.dee.L167.597"] = "Adiós, adiós |PLAYERNAME|.",
  ["data.otservbr.global.npc.al.dee.L168.598"] = "Eche un vistazo a la ventana comercial a su izquierda.",
  ["data.otservbr.global.npc.albinius.L267.1035"] = "Saludos, peregrino. Bienvenidos a los pasillos de la esperanza. Somos los guardianes de este {temple} y damos la bienvenida a todos los que estén dispuestos a contribuir.",
  ["data.otservbr.global.npc.albinius.L268.1036"] = "Oh... adiós, niña.",
  ["data.otservbr.global.npc.alesar.L206.1591"] = "Finalmente.",
  ["data.otservbr.global.npc.alesar.L207.1592"] = "Finalmente.",
  ["data.otservbr.global.npc.alesar.L208.1593"] = "A su servicio, simplemente explore mis productos.",
  ["data.otservbr.global.npc.alexander.L171.1567"] = "[ES] Hi there |PLAYERNAME|, and welcome to the {magic} store.",
  ["data.otservbr.global.npc.alexander.L172.1568"] = "Nos vemos, |PLAYERNAME|.",
  ["data.otservbr.global.npc.alexander.L173.1569"] = "Nos vemos, |PLAYERNAME|.",
  ["data.otservbr.global.npc.alexander.L174.1570"] = "Por supuesto, simplemente navega por mis productos. ¿O quieres mirar sólo",
  ["data.otservbr.global.npc.alia.L148.1158"] = "¡Bienvenido, joven |PLAYERNAME|! Si estás gravemente herido o envenenado, puedo {heal} gratis.",
  ["data.otservbr.global.npc.alia.L149.1159"] = "Recuerda: si estás gravemente herido o envenenado, puedo curarte gratis.",
  ["data.otservbr.global.npc.alia.L150.1160"] = "¡Que los dioses te bendigan, |PLAYERNAME|!",
  ["data.otservbr.global.npc.alkestios.L130.1473"] = "¡La bendición de la naturaleza, viajero! Que no te afecte ninguna fuerza siniestra.",
  ["data.otservbr.global.npc.alkestios.L131.1474"] = "Que tu camino sea siempre llano.",
  ["data.otservbr.global.npc.alkestios.L132.1475"] = "Que tu camino sea siempre llano.",
  ["data.otservbr.global.npc.altar.L83.730"] = "Arrodíllate ante el poder devorador de la sangre en descomposición.",
  ["data.otservbr.global.npc.altar.L84.731"] = "Chao.",
  ["data.otservbr.global.npc.altar.L85.732"] = "Adiós, |PLAYERNAME|.",
  ["data.otservbr.global.npc.alyxo.L210.798"] = "Bueno, adiós entonces.",
  ["data.otservbr.global.npc.alyxo.L53.795"] = "¿Cómo podría ayudarte?",
  ["data.otservbr.global.npc.alyxo.L56.796"] = "¿Cómo podría ayudarte?",
  ["data.otservbr.global.npc.alyxo.L59.797"] = "¿Cómo podría ayudarte?",
  ["data.otservbr.global.npc.amanda.L200.1226"] = "¡Bienvenido, joven |PLAYERNAME|! Si estás gravemente herido o envenenado, puedo {heal} gratis.",
  ["data.otservbr.global.npc.amanda.L201.1227"] = "Recuerda: si estás gravemente herido o envenenado, puedo curarte gratis.",
  ["data.otservbr.global.npc.amanda.L202.1228"] = "¡Que los dioses te bendigan, |PLAYERNAME|!",
  ["data.otservbr.global.npc.ambassador.of.rathleton.L86.343"] = "Saludos amigo.",
  ["data.otservbr.global.npc.ambassador.of.rathleton.L87.344"] = "Bueno, adiós entonces.",
  ["data.otservbr.global.npc.amber.L426.528"] = "Sí, nos vemos luego.",
  ["data.otservbr.global.npc.amber.L427.529"] = "Hasta luego, |PLAYERNAME|.",
  ["data.otservbr.global.npc.amber.L428.530"] = "Hola, que bueno verte |PLAYERNAME|. ¿Estás aquí para escuchar algunas historias de mi {adventures} o necesitas {help}?",
  ["data.otservbr.global.npc.anderson.L100.133"] = "[ES] Ahoi, young man |PLAYERNAME| and welcome to the Nordic Tibia Ferries. If you need a {passage}, let me know.",
  ["data.otservbr.global.npc.anderson.L101.134"] = "Adiós. De nada.",
  ["data.otservbr.global.npc.andrew.lyze.L101.514"] = "Hola, soy el director de este {monument}. El {sarcophagus} frente a usted se estableció para evitar que las personas vayan {down} allí. Pero dudo que este paso sea suficiente.",
  ["data.otservbr.global.npc.andrew.lyze.L103.515"] = "Bueno, veamos si tu misión tuvo éxito. Sólo tráeme todo lo necesario {materials}.",
  ["data.otservbr.global.npc.andrew.lyze.L105.516"] = "Si desenterraste los tres cristales en cantidad suficiente y obtuviste la glándula venenosa, ¡la carga de tu brújula puede comenzar! Por primera vez será cargado por el cristal violeta. ¿Listo para {unleash} el poder de los cristales?",
  ["data.otservbr.global.npc.andrew.lyze.L107.517"] = "Saludos.",
  ["data.otservbr.global.npc.andrew.lyze.L263.518"] = "Bueno, adiós entonces.",
  ["data.otservbr.global.npc.andrew.lyze.L264.519"] = "Adiós.",
  ["data.otservbr.global.npc.anerui.L71.1487"] = "[EN] Ashari |PLAYERNAME|.",
  ["data.otservbr.global.npc.anerui.L72.1488"] = "Asha Thrázi.",
  ["data.otservbr.global.npc.anerui.L73.1489"] = "Asha Thrázi.",
  ["data.otservbr.global.npc.aneus.L130.1323"] = "Saludos aventurero |PLAYERNAME|. ¿Qué te lleva a mí?",
  ["data.otservbr.global.npc.aneus.L131.1324"] = "¡Adiós y cuidarte!",
  ["data.otservbr.global.npc.angelina.L58.143"] = "Hay que alabar a los dioses porque finalmente me salvé. No tengo muchas posesiones mundanas, pero por favor acepta una pequeña recompensa, ¿verdad?",
  ["data.otservbr.global.npc.angelina.L60.144"] = "¡Gracias por salvarme la vida! ¿Debería teletransportarte fuera de la Catedral Oscura?",
  ["data.otservbr.global.npc.angelina.L84.145"] = "Que los dioses te bendigan.",
  ["data.otservbr.global.npc.angelina.L85.146"] = "Que los dioses te bendigan.",
  ["data.otservbr.global.npc.angelo.L153.1447"] = "Bueno, adiós entonces.",
  ["data.otservbr.global.npc.angelo.L58.1443"] = "¿El Druid de Crunor? ¿Te dijo que aquí apareció una nueva cueva? Así es. Soy el jefe de un {project} que intenta saber más sobre este nuevo {area}.",
  ["data.otservbr.global.npc.angelo.L60.1444"] = "¡Apártate de mi camino! Mataste a esta hermosa criatura. No tengo nada más que decir. ¡Maldito druida de Crunor!",
  ["data.otservbr.global.npc.angelo.L62.1445"] = "¿Cómo va tu {mission}?",
  ["data.otservbr.global.npc.angelo.L64.1446"] = "¿El Druid de Crunor? ¿Te dijo que aquí apareció una nueva cueva? Así es. Soy el líder de un proyecto que intenta conocer más sobre esta nueva área.",
  ["data.otservbr.global.npc.angus.L633.1450"] = "Saludos, ¿qué puedo hacer por ti?",
  ["data.otservbr.global.npc.appaloosa.L109.1145"] = "[ES] Salutations, |PLAYERNAME| I guess you are here for the {horses}.",
  ["data.otservbr.global.npc.archery.L64.538"] = "¡Bienvenido a la tienda de Tiro con Arco!",
  ["data.otservbr.global.npc.archery.L65.539"] = "Por favor regresa de vez en cuando.",
  ["data.otservbr.global.npc.archery.L66.540"] = "Por favor regresa de vez en cuando.",
  ["data.otservbr.global.npc.archery.rook.L63.70"] = "[ES] Welcome to Archery's Rook shop.",
  ["data.otservbr.global.npc.archery.rook.L64.71"] = "Por favor regresa de vez en cuando.",
  ["data.otservbr.global.npc.archery.rook.L65.72"] = "Por favor regresa de vez en cuando.",
  ["data.otservbr.global.npc.ariella.L161.242"] = "Hola.",
  ["data.otservbr.global.npc.arito.L117.1343"] = "Visítenos nuevamente.",
  ["data.otservbr.global.npc.arito.L118.1344"] = "Visítenos nuevamente.",
  ["data.otservbr.global.npc.arito.L119.1345"] = "Claro, navega por mis ofertas.",
  ["data.otservbr.global.npc.arito.L55.1341"] = "Gracias a dios estas de regreso!! ¿Encontraste... err... de qué estábamos hablando?",
  ["data.otservbr.global.npc.arito.L57.1342"] = "Sé de luto, peregrino en carne. Ser llorado en mi taberna.",
  ["data.otservbr.global.npc.arkarra.L54.501"] = "...",
  ["data.otservbr.global.npc.arkarra.L55.502"] = "...",
  ["data.otservbr.global.npc.arkarra.L56.503"] = "...",
  ["data.otservbr.global.npc.arkulius.L183.893"] = "Adiós y por favor mantente alejado, ¿vale?",
  ["data.otservbr.global.npc.arkulius.L184.894"] = "¡Por fin! Las cosas buenas les llegan a quienes esperan.",
  ["data.otservbr.global.npc.armenius.L74.643"] = "Oh, el descaro. Ve con las ratas que te criaron.",
  ["data.otservbr.global.npc.armenius.L86.644"] = "Ah, un aventurero. Sea saludado y tome asiento. ¿Cómo puedo {serve} ti?",
  ["data.otservbr.global.npc.aruda.L256.1338"] = "Espero verte pronto.",
  ["data.otservbr.global.npc.aruda.L257.1339"] = "Adiós, |PLAYERNAME|. Realmente espero que volvamos a hablar pronto.",
  ["data.otservbr.global.npc.aruda.L64.1336"] = "Oh, hola |PLAYERNAME|, ¡tu cabello se ve genial! ¿Quién lo hizo por ti?",
  ["data.otservbr.global.npc.aruda.L67.1337"] = "¡Hola, guapo! Es un placer conocerte, |PLAYERNAME|. Con mucho gusto tengo tiempo para {chat} un poco.",
  ["data.otservbr.global.npc.ashari.L52.1581"] = "¡Hola, extraño! Estas cuevas deben parecerte extrañas. Me pregunto qué te trae por aquí... ¿quizás te interese algún trabajo? Hay varias tareas en las que podría necesitar ayuda.",
  ["data.otservbr.global.npc.ashari.L53.1582"] = "¡Chao!",
  ["data.otservbr.global.npc.ashari.L54.1583"] = "¡Chao!",
  ["data.otservbr.global.npc.asima.L179.1417"] = "Por supuesto, simplemente navega por mis productos. ¿O quieres mirar sólo",
  ["data.otservbr.global.npc.atur.L76.727"] = "¿Sí? ¿Qué puedo hacer por ti, |PLAYERNAME|? ¿Negocios bancarios, tal vez?",
  ["data.otservbr.global.npc.atur.L77.728"] = "Que tenga un lindo día.",
  ["data.otservbr.global.npc.atur.L78.729"] = "Que tenga un lindo día.",
  ["data.otservbr.global.npc.aurita.L114.171"] = "¡Saludos viajero!",
  ["data.otservbr.global.npc.aurita.L115.172"] = "Que tu camino sea siempre llano.",
  ["data.otservbr.global.npc.aurita.L116.173"] = "Que tu camino sea siempre llano.",
  ["data.otservbr.global.npc.avar.tar.L137.859"] = "¡Saludos viajero |PLAYERNAME|!",
  ["data.otservbr.global.npc.avar.tar.L138.860"] = "Hasta luego, |PLAYERNAME|.",
  ["data.otservbr.global.npc.avar.tar.L139.861"] = "Hasta luego, |PLAYERNAME|.",
  ["data.otservbr.global.npc.awarness.of.the.emperor.L50.141"] = "No estoy aquí para pelear contigo, tonto. Nos guste o no, tendremos que trabajar juntos para detener la catástrofe que usted y ese sacerdote han iniciado.",
  ["data.otservbr.global.npc.awarness.of.the.emperor.L52.142"] = "Saludos, mortal. Ten en cuenta que estás poniendo a prueba mi paciencia mientras hablamos.",
  ["data.otservbr.global.npc.azalea.L148.851"] = "¡Bienvenido, joven |PLAYERNAME|! Si estás gravemente herido o envenenado, puedo {heal} gratis.",
  ["data.otservbr.global.npc.azalea.L149.852"] = "Recuerda: si estás gravemente herido o envenenado, puedo curarte gratis.",
  ["data.otservbr.global.npc.azalea.L150.853"] = "¡Que los dioses te bendigan, |PLAYERNAME|!",
  ["data.otservbr.global.npc.baa.leal.L158.273"] = "¡Retírate, soldado!",
  ["data.otservbr.global.npc.bambi.bonecrusher.L76.573"] = "¡VIVA LA REINA!",
  ["data.otservbr.global.npc.bambi.bonecrusher.L77.574"] = "¡VIVA LA REINA!",
  ["data.otservbr.global.npc.bambi.bonecrusher.L78.575"] = "¡VIVA LA REINA!",
  ["data.otservbr.global.npc.barazbaz.L93.18"] = "[EN] Oh, hello there!",
  ["data.otservbr.global.npc.barbara.L84.1299"] = "¡VIVA LA REINA!",
  ["data.otservbr.global.npc.barbara.L85.1300"] = "¡VIVA LA REINA! ¡Puedes irte ahora!",
  ["data.otservbr.global.npc.barnabas.dee.L130.1046"] = "Bienvenidos a mi humilde morada. Si vienes por el nuevo hechicero {spells}, has venido al lugar correcto.",
  ["data.otservbr.global.npc.barnabas.dee.L131.1047"] = "Cuídate, niño",
  ["data.otservbr.global.npc.barnabas.dee.L132.1048"] = "[ES] 'The impetuosity of youth', as my friend Mordecai would say.",
  ["data.otservbr.global.npc.bashira.L63.1584"] = "Bienvenido, |PLAYERNAME|.",
