  ["data.otservbr.global.npc.carina.L97.831"] = "Bienvenido, |PLAYERNAME|. Estoy deseando comerciar con usted.",
  ["data.otservbr.global.npc.carlos.L100.1093"] = "Bienvenido de nuevo |PLAYERNAME|, espero que hayas cambiado de opinión y me traigas algo de {meat}. Incluso te daré algo de oro por ello.",
  ["data.otservbr.global.npc.carlos.L103.1094"] = "¡Bienvenido de nuevo, |PLAYERNAME|! ¿Tuviste una caza exitosa y llevaste un trozo de {meat} o jamón contigo?",
  ["data.otservbr.global.npc.carlos.L107.1095"] = "¡Bienvenida de nuevo, Isleth Eagonst! ¿Todavía tienes ese trozo de carne o jamón? Si es así, pídeme un {trade} y te daré algo de oro por él.",
  ["data.otservbr.global.npc.carlos.L110.1096"] = "¡Bienvenido de nuevo, |PLAYERNAME|! ¿Dónde pusiste ese delicioso trozo de comida? ¿Lo comiste tú mismo? Bueno, si encuentras otro, vuelve.",
  ["data.otservbr.global.npc.carlos.L115.1097"] = "¡Hola, |PLAYERNAME|! Bueno, así es como funciona el comercio con NPC como yo. ¡Creo que ya estás listo para cruzar el puente hacia Rookgaard! ¡Cuidarse!",
  ["data.otservbr.global.npc.carlos.L121.1098"] = "¡Hola de nuevo, |PLAYERNAME|! ¿Qué sigues haciendo aquí? ¡Deberías cruzar el puente hacia la aldea Rookgaard ahora!",
  ["data.otservbr.global.npc.carlos.L241.1099"] = "¡Muy lindo! ¡Comida para mí! ¡Véndemelo, rápido! Una vez que me hayas vendido tu comida, simplemente di {ready} para informarme que ya terminaste.",
  ["data.otservbr.global.npc.carlos.L242.1100"] = "¡Adiós |PLAYERNAME|!.",
  ["data.otservbr.global.npc.carlos.L243.1101"] = "Adiós viajero y disfruta de tu estancia en Rookgaard.",
  ["data.otservbr.global.npc.carlos.L86.1089"] = "¡Sea saludado, |PLAYERNAME|! Como sastre y comerciante, tengo que decir: tenemos que hacer algo con respecto a su {outfit}, ¿de acuerdo?",
  ["data.otservbr.global.npc.carlos.L91.1090"] = "Oye, pensé que ibas a huir, pero por suerte volviste. Te mostraré cómo cambiar tu {outfit}, ¿de acuerdo?",
  ["data.otservbr.global.npc.carlos.L94.1091"] = "¡Bienvenido de nuevo! Sabes, después de brindarte mi pequeño servicio de outfit, me gustaría pedirte un pequeño favor. ¿Puedes {help} mí?",
  ["data.otservbr.global.npc.carlos.L97.1092"] = "Hola, |PLAYERNAME|, aún no respondiste mi pregunta. ¿Podrías ayudarme a conseguir {food}? Incluso te daré algo de oro por ello.",
  ["data.otservbr.global.npc.cassino.L250.349"] = "¡Bienvenidos al Casino! Aquí jugamos con: \\n [PAGO 180%] {HIGH / LOW}: Alto para 4, 5, 6 y Bajo para 1, 2 y 3 - {ODD / EVEN }: Impar para 1, 3, 5 y Par para 2, 4 y 6 \\n [PAGO 500%] {NUMBERS}: Tú eliges el número, y si aciertas… {$$$$$}",
