  ["data.otservbr.global.npc.sam.L155.912"] = "Adiós y vuelve otra vez.",
  ["data.otservbr.global.npc.sandomo.L176.5"] = "Mmm. Saludos.",
  ["data.otservbr.global.npc.sandomo.L177.6"] = "Alabado sea los dioses, me despido de vosotros.",
  ["data.otservbr.global.npc.sandra.L142.1395"] = "[EN] Hello |PLAYERNAME|, welcome to the fluid and potion {shop} of Edron.",
  ["data.otservbr.global.npc.sandra.L143.1396"] = "Adiós, |PLAYERNAME|, vuelve pronto.",
  ["data.otservbr.global.npc.sandra.L144.1397"] = "Adiós, |PLAYERNAME|, vuelve pronto.",
  ["data.otservbr.global.npc.sandra.L145.1398"] = "Por supuesto, simplemente navega por mis productos. Por cierto, si quieres unirte a nuestro sistema de bonificación por depósito de matraces y viales, tienes que contarme sobre eso {deposit}.",
  ["data.otservbr.global.npc.sane.mage.L89.1503"] = "...eh... ¿hola? Sí...? Bueno, si... si tienes alguna pregunta... ni siquiera estoy aquí.",
  ["data.otservbr.global.npc.sane.mage.L90.1504"] = "Sí... entonces, adiós.",
  ["data.otservbr.global.npc.sane.mage.L91.1505"] = "Sí... entonces, adiós.",
  ["data.otservbr.global.npc.santiago.L101.959"] = "¡Bienvenido de nuevo! ¿Dónde estábamos...? Ah, claro, ¡te pregunté si viste tu 'level up'! ¿Lo hiciste, {right}?",
  ["data.otservbr.global.npc.santiago.L104.960"] = "¡Bienvenido de nuevo! ¿Dónde estábamos...? Ah, claro, te pregunté si esas desagradables cucarachas {hurt} ¡te! ¿Lo hicieron?",
  ["data.otservbr.global.npc.santiago.L107.961"] = "¡Bienvenido de nuevo! ¿Dónde estábamos...? Ah, claro, te pregunté si debería demostrarte algún daño. ¿Hagámoslo, {okay}?",
  ["data.otservbr.global.npc.santiago.L110.962"] = "¡Bienvenido de nuevo! ¿Dónde estábamos...? Ah, cierto, estaba a punto de mostrarte cómo se recupera la salud, ¿verdad?",
  ["data.otservbr.global.npc.santiago.L113.963"] = "¡Bienvenido de nuevo! ¿Dónde estábamos...? Ah, cierto, ¿te di un pescado para comer?",
  ["data.otservbr.global.npc.santiago.L116.964"] = "¡Bienvenido de nuevo! ¿Dónde estábamos...? ¡Ah, claro, te pregunté si viste a Zirella! ¿Acaso tú?",
  ["data.otservbr.global.npc.santiago.L119.965"] = "¡Hola de nuevo, |PLAYERNAME|! Es genial verte. Si quieres podemos charlar un poco. Simplemente use el {keywords} resaltado nuevamente para elegir un {topic}.",
  ["data.otservbr.global.npc.santiago.L250.966"] = "¡Cuídate, |PLAYERNAME|!.",
  ["data.otservbr.global.npc.santiago.L251.967"] = "Adiós viajero y disfrute de su estadía en Rookgaard.",
  ["data.otservbr.global.npc.santiago.L70.954"] = "Hola |PLAYERNAME|, ¡encantado de verte en Rookgaard! Te vi pasar y me pregunté si podrías ayudarme. ¿Podrías? ¡Por favor, diga {yes}!",
  ["data.otservbr.global.npc.santiago.L73.955"] = "¡Oh, |PLAYERNAME|, eres tú otra vez! Probablemente sea de mala educación molestar a un aventurero ocupado como tú, pero realmente necesito ayuda. ¡Por favor, diga {yes}!",
  ["data.otservbr.global.npc.santiago.L80.956"] = "¡Bienvenido de nuevo, |PLAYERNAME|! Ahh, encontraste mi cofre. Déjame echarte un vistazo. ¿Te pusiste ese abrigo, {yes}?",
  ["data.otservbr.global.npc.santiago.L83.957"] = "¡Oye, quiero darte un arma gratis! ¡No deberías negarte a eso, de hecho deberías decir '{yes}'!",
  ["data.otservbr.global.npc.santiago.L90.958"] = "¡Buen trabajo! ¡Por eso te otorgaré 100 puntos de experiencia! Ah, ¿qué fue eso? Creo que avanzaste un nivel, {right}?",
  ["data.otservbr.global.npc.sarina.L86.73"] = "Oh, por favor entra, |PLAYERNAME|. ¿Qué puedo hacer por ti? Si necesitas equipo de aventura, pídeme un {trade}.",
  ["data.otservbr.global.npc.sarina.L87.74"] = "Adiós, |PLAYERNAME|.",
  ["data.otservbr.global.npc.sarina.L88.75"] = "Adiós, |PLAYERNAME|.",
  ["data.otservbr.global.npc.sarina.L89.76"] = "Por supuesto, simplemente navega por mis productos. {Footballs} debe comprarse por separado.",
  ["data.otservbr.global.npc.scrutinon.L101.1548"] = "|PLAYERNAME|. He estado observando tu destino durante bastante tiempo. Ya era hora de que vinieras aquí. ¿Buscas entrar a la isla dividida de Quirefang o viajar de regreso desde donde viniste?",
  ["data.otservbr.global.npc.sebastian.L116.1348"] = "Saludos, atrevido aventurero. Si necesitas un {passage}, házmelo saber.",
  ["data.otservbr.global.npc.sebastian.L117.1349"] = "Adiós.",
  ["data.otservbr.global.npc.sebastian.L118.1350"] = "Ah, bueno.",
  ["data.otservbr.global.npc.sebastian.nargor.L68.1109"] = "Saludos, atrevido aventurero. Si necesitas un {passage}, házmelo saber.",
  ["data.otservbr.global.npc.sebastian.nargor.L69.1110"] = "Adiós.",
  ["data.otservbr.global.npc.sebastian.nargor.L70.1111"] = "Ah, bueno.",
  ["data.otservbr.global.npc.serafin.L78.1045"] = "¡Bienvenidos a mi tienda de frutas y verduras, |PLAYERNAME|! Pídeme un {trade} si quieres ver mis productos.",
  ["data.otservbr.global.npc.servant.sentry.L94.222"] = "El. Limo. Tiene. Entró. Nuestro. Maestro. Tiene. ¡Izquierda! Nosotros. Debe. Ayuda.",
  ["data.otservbr.global.npc.servant.sentry.L95.223"] = "Adiós. Humano. ¡Ser!",
  ["data.otservbr.global.npc.servant.sentry.L96.224"] = "Adiós. Humano. ¡Ser!",
  ["data.otservbr.global.npc.seymour.L243.46"] = "¡Adiós! Y recuerda: ¡No correr de un lado a otro en la academia!",
