  ["data.otservbr.global.npc.shoddy.beggar.L172.53"] = "¿Qué deseas? ¿Escuchar al viejo loco? Si no tienes nada de sobra, déjame en paz.",
  ["data.otservbr.global.npc.shoddy.beggar.L173.54"] = "Sí, lo que sea.",
  ["data.otservbr.global.npc.shoddy.beggar.L174.55"] = "Sí, lo que sea.",
