  ["data.otservbr.global.npc.siestaar.L76.570"] = "¿Sí? ¿Qué puedo hacer por ti, |PLAYERNAME|? ¿Negocios bancarios, tal vez?",
  ["data.otservbr.global.npc.siestaar.L77.571"] = "Que tenga un lindo día.",
  ["data.otservbr.global.npc.siestaar.L78.572"] = "Que tenga un lindo día.",
  ["data.otservbr.global.npc.siflind.L214.1557"] = "Sea saludado, |PLAYERNAME|. Si necesitas pociones o equipo mágico, pregúntame sobre mi {offers}.",
  ["data.otservbr.global.npc.sigurd.L144.1168"] = "¡Bienvenido a la tienda de magia, |PLAYERNAME|! Pídeme un intercambio si necesitas algo.",
