  ["data.otservbr.global.npc.simon.the.beggar.L315.1138"] = "Hola |PLAYERNAME|. Soy un hombre pobre. Por favor, ayúdame.",
  ["data.otservbr.global.npc.simon.the.beggar.L316.1139"] = "Que tenga un lindo día.",
  ["data.otservbr.global.npc.simon.the.beggar.L317.1140"] = "Que tenga un lindo día.",
  ["data.otservbr.global.npc.sinclair.L157.1276"] = "Saludos |PLAYERNAME|. Tengo muy poco tiempo, por favor que sea lo más breve posible. Es posible que pueda ayudarte si estás aquí para ayudarnos con cualquiera de nuestras tareas o misiones.",
  ["data.otservbr.global.npc.sinclair.L158.1277"] = "Adiós y buena suerte |PLAYERNAME|.",
  ["data.otservbr.global.npc.sinclair.L159.1278"] = "Adiós y buena suerte |PLAYERNAME|.",
  ["data.otservbr.global.npc.sissek.L71.1049"] = "¿Sí? ¿Qué puedo hacer por ti, |PLAYERNAME|? ¿Negocios bancarios, tal vez?",
  ["data.otservbr.global.npc.sissek.L72.1050"] = "Que tenga un lindo día.",
  ["data.otservbr.global.npc.sissek.L73.1051"] = "Que tenga un lindo día.",
  ["data.otservbr.global.npc.sister.of.jack.L106.611"] = "Hola, hola. ¿Qué puedo hacer por ti?",
  ["data.otservbr.global.npc.skjaar.L89.1578"] = "¡Otra criatura que cree piensa que la fuerza física es más importante que la sabiduría! ¿Por qué me molestas?",
  ["data.otservbr.global.npc.skjaar.L90.1579"] = "¡Adiós, |PLAYERNAME|!",
  ["data.otservbr.global.npc.skjaar.L91.1580"] = "¡Huye, indigno |PLAYERNAME|!",
  ["data.otservbr.global.npc.spectulus.L492.816"] = "¡Hola |PLAYERNAME|! Llegas tarde, ¿no tienes noción del tiempo? Mi misión es de suma importancia. Si no estás interesado en ayudarme, es mejor que te vayas.",
  ["data.otservbr.global.npc.spectulus.L493.817"] = "Si si. Adiós |PLAYERNAME|.",
  ["data.otservbr.global.npc.spectulus.L494.818"] = "Si si. Adiós |PLAYERNAME|.",
  ["data.otservbr.global.npc.spectulus.L67.814"] = "¡Hola |PLAYERNAME|! Llegas tarde, ¿no tienes noción del tiempo? Mi misión es de suma importancia. Si no estás interesado en ayudarme, es mejor que te vayas.",
  ["data.otservbr.global.npc.spectulus.L70.815"] = "Ah hola de nuevo |PLAYERNAME|! Todavía tengo uno o dos {missions} más para ti. También hay algunos {tasks} que alguien debe atender.",
  ["data.otservbr.global.npc.stricken.soul.L53.1482"] = "Este lugar está... embrujado... presta atención a mi advertencia... ¡hay... fantasmas aquí...! ¿Por qué me das esa... mirada? Estoy seguro de que aquí hay fantasmas, ¡los he visto! ¿Me crees?",
  ["data.otservbr.global.npc.stricken.soul.L55.1483"] = "Saludos.",
  ["data.otservbr.global.npc.stutch.L84.1270"] = "¡VIVA EL REY!",
  ["data.otservbr.global.npc.stutch.L85.1271"] = "¡VIVA EL REY! ¡Puedes irte ahora!",
  ["data.otservbr.global.npc.sundara.L170.1087"] = "Por supuesto, simplemente navega por mis productos. ¿O quieres mirar sólo",
  ["data.otservbr.global.npc.suzy.L76.1112"] = "¿Sí? ¿Qué puedo hacer por ti, |PLAYERNAME|? ¿Negocios bancarios, tal vez?",
  ["data.otservbr.global.npc.suzy.L77.1113"] = "Que tenga un lindo día.",
  ["data.otservbr.global.npc.suzy.L78.1114"] = "Que tenga un lindo día.",
  ["data.otservbr.global.npc.sven.L55.603"] = "Iskan me dijo que mataste perros esquimales aquí en Svargrond. Seré indulgente contigo y no te prohibiré el acceso a Svargrond. Pero tienes que pagarme una compensación de 1500 de oro por cada husky que hayas matado. ¿Estás dispuesto a pagar?",
  ["data.otservbr.global.npc.sven.L57.604"] = "[EN] Be greeted, |PLAYERNAME|! What brings you {here}?",
  ["data.otservbr.global.npc.swolt.L111.235"] = "Echa un vistazo, pero ni un sorbo antes de pagar. Y espero que siga así y no se te ocurra ninguna idea extraña sobre {rice}.",
  ["data.otservbr.global.npc.taegen.L203.752"] = "¡Sea saludado, ser mortal!",
  ["data.otservbr.global.npc.taegen.L204.753"] = "Que la iluminación sea tu camino, |PLAYERNAME|.",
  ["data.otservbr.global.npc.taegen.L205.754"] = "Que la iluminación sea tu camino, |PLAYERNAME|.",
  ["data.otservbr.global.npc.taegen.L206.755"] = "Estoy tallando pernos y flechas y también fabrico arcos y lanzas. Si quieres comprar municiones, echa un vistazo.",
  ["data.otservbr.global.npc.talila.L61.1453"] = "Saludos, comienzo mortal.",
  ["data.otservbr.global.npc.talila.L62.1454"] = "Sí, tengo algunas pociones y runas si estás interesado. ¿O quieres comprar solo pociones o solo runas? Oh, si quieres vender o comprar gemas, también puedes preguntarme.",
  ["data.otservbr.global.npc.talila.L63.1455"] = "Que la iluminación sea tu camino, |PLAYERNAME|.",
  ["data.otservbr.global.npc.tamerin.L58.283"] = "[EN] Have you the {animal cure}?",
  ["data.otservbr.global.npc.tamerin.L60.284"] = "¿Has matado a {morik}?",
  ["data.otservbr.global.npc.tamerin.L62.285"] = "Hola, ¿qué te trae por aquí?",
  ["data.otservbr.global.npc.tamoril.L113.1311"] = "Otro mortal molesto que cree que su oro supera su valor nutricional.",
  ["data.otservbr.global.npc.tamoril.L61.1310"] = "Sólo podrás hablar del Primer Dragón entre el 14 de enero y el 12 de febrero.",
  ["data.otservbr.global.npc.tandros.L160.196"] = "Por supuesto, simplemente navega por mis productos. ¿O quieres mirar sólo",
  ["data.otservbr.global.npc.tanyt.L100.1187"] = "Ah, el viento trae otro visitante. Bienvenido, querido invitado. ¿Estás buscando un {passage} con mi alfombra?",
  ["data.otservbr.global.npc.tanyt.L101.1188"] = "Adiós. Recomiéndenos si quedó satisfecho con nuestro servicio.",
  ["data.otservbr.global.npc.tanyt.L102.1189"] = "Bueno, adiós entonces.",
  ["data.otservbr.global.npc.tarak.inner.L88.682"] = "[EN] Can I interest you in a trip to the {monument tower}?",
  ["data.otservbr.global.npc.tarak.sunken.L75.868"] = "[EN] Want to go back to Yalahar? Just ask me for a free {passage}.",
  ["data.otservbr.global.npc.tarun.L116.1563"] = "Saludos!",
  ["data.otservbr.global.npc.tarun.L117.1564"] = "Despedida.",
  ["data.otservbr.global.npc.tarun.L118.1565"] = "Por supuesto, sólo eche un vistazo.",
  ["data.otservbr.global.npc.tarun.L121.1566"] = "Despedida.",
  ["data.otservbr.global.npc.tefrit.L119.537"] = "Bueno, adiós entonces.",
