  ["data.otservbr.global.npc.tefrit.L64.536"] = "¿Cómo podría ayudarte?",
  ["data.otservbr.global.npc.tehlim.L76.419"] = "Nos vemos amigo.",
  ["data.otservbr.global.npc.tehlim.L77.420"] = "Nos vemos amigo.",
  ["data.otservbr.global.npc.tehlim.L78.421"] = "Hola. Me alegro mucho que alguien me haya encontrado. ¡¿Los conociste?!",
  ["data.otservbr.global.npc.telas.L103.1028"] = "Hola!",
  ["data.otservbr.global.npc.telas.golem.L54.279"] = "¿Dónde... estoy?",
  ["data.otservbr.global.npc.telas.golem.L55.280"] = "Adiós.",
  ["data.otservbr.global.npc.telas.golem.L56.281"] = "Adiós.",
  ["data.otservbr.global.npc.tereban.L61.592"] = "Saludos amigo. Qué bueno que estás apareciendo.",
  ["data.otservbr.global.npc.terrence.L75.456"] = "Hola, seguramente estás interesado en ayudar a la guardia de la ciudad Rathleton, ¿verdad? Claro, sobre todo ahora que los temidos minotauros ganan cada día más terreno.",
  ["data.otservbr.global.npc.tesha.L76.913"] = "¿Sí? ¿Qué puedo hacer por ti, |PLAYERNAME|? ¿Negocios bancarios, tal vez?",
  ["data.otservbr.global.npc.tesha.L77.914"] = "Que tenga un lindo día.",
