  ["data.otservbr.global.npc.testserver.assistant.L116.455"] = "[EN] Hey |PLAYERNAME|. I'm Testserver Assistant and I can give {money}, {experience} and {blessing} which will be useful for testing on",
  ["data.otservbr.global.npc.testserver.assistant.L89.453"] = "Ya estás bendecido.",
  ["data.otservbr.global.npc.testserver.assistant.L98.454"] = "Recibiste el resto",
  ["data.otservbr.global.npc.thanita.L86.1073"] = "¿Cómo pudiste acercarte sigilosamente así? ¡Pensé que eras uno de ELLOS! Bueno, ya que no lo eres, ¿qué te trae a este desierto?",
  ["data.otservbr.global.npc.thanita.L87.1074"] = "Cuídate mucho viajero. Sería una pena perder a un vagabundo tan valiente ante esos monstruos verdes.",
  ["data.otservbr.global.npc.thanita.L88.1075"] = "Cuídate mucho viajero. Sería una pena perder a un vagabundo tan valiente ante esos monstruos verdes.",
  ["data.otservbr.global.npc.the.beggar.king.L103.328"] = "¡Hola! Pareces alguien en un {mission}.",
  ["data.otservbr.global.npc.the.beggar.king.L104.329"] = "¡Adiós!",
  ["data.otservbr.global.npc.the.blind.prophet.L69.426"] = "Sea saludado, amigo de los simios.",
  ["data.otservbr.global.npc.the.bone.master.L138.464"] = "Bienvenidos a mi pequeño reino.",
  ["data.otservbr.global.npc.the.bone.master.L139.465"] = "Nos volveremos a encontrar.",
  ["data.otservbr.global.npc.the.crone.L54.397"] = "[EN] Be greeted, |PLAYERNAME|... mortal.",
  ["data.otservbr.global.npc.the.dream.master.L134.676"] = "Sea saludado, visitante.",
  ["data.otservbr.global.npc.the.dream.master.L135.677"] = "Adiós. Que los dioses cuiden tu camino.",
  ["data.otservbr.global.npc.the.empress.L78.443"] = "Saludos.",
  ["data.otservbr.global.npc.the.empress.L84.444"] = "Bueno, adiós entonces.",
  ["data.otservbr.global.npc.the.first.dragon.L149.1115"] = "Hola, mi compañero de entrenamiento. A veces deberíamos tener otra pelea. Creo que quizás te hayas ganado una pequeña recompensa.",
  ["data.otservbr.global.npc.the.librarian.L86.394"] = "Saludos, querido invitado. Si estás interesado en artículos de papel como libros o pergaminos, pregúntame por un intercambio.",
  ["data.otservbr.global.npc.the.librarian.L87.395"] = "Bueno, adiós entonces.",
  ["data.otservbr.global.npc.the.lootmonger.L72.1308"] = "¡Ah, un cliente! ¡Sea saludado, |PLAYERNAME|! Compro todo tipo de botín, ¿te gustaría un {trade}? También puedo mostrarte mi {shop options}.",
  ["data.otservbr.global.npc.the.lootmonger.L73.1309"] = "¡Ah, un cliente! ¡Sea saludado, |PLAYERNAME|! Compro todo tipo de botín, ¿podrías mirar?",
  ["data.otservbr.global.npc.the.oracle.L164.499"] = "¡VUELVE CUANDO ESTÉS PREPARADO PARA ENFRENTAR TU DESTINO!",
  ["data.otservbr.global.npc.the.oracle.L165.500"] = "¡VUELVE CUANDO ESTÉS PREPARADO PARA ENFRENTAR TU DESTINO!",
  ["data.otservbr.global.npc.the.orc.king.L61.114"] = "¡Hurra! ¿Crees que eres fuerte ahora? ¡Nunca escaparás de mi ira! ¡Soy inmortal!",
  ["data.otservbr.global.npc.the.queen.of.the.banshees.L215.943"] = "Sea saludado, querido visitante. Ven y {stay}... un rato.",
  ["data.otservbr.global.npc.the.queen.of.the.banshees.L216.944"] = "Nos volveremos a encontrar, |PLAYERNAME|.",
  ["data.otservbr.global.npc.the.queen.of.the.banshees.L217.945"] = "Sí, huye de la muerte. Pero sepan que siempre estará un paso detrás de ustedes.",
  ["data.otservbr.global.npc.thorgrin.L67.258"] = "¡Bienvenido, |PLAYERNAME|! Que la tierra os proteja en los terrenos pedregosos. Si necesitas un respaldo {passage}, puedo ayudarte.",
  ["data.otservbr.global.npc.thorgrin.L68.259"] = "Adiós.",
  ["data.otservbr.global.npc.thorgrin.L69.260"] = "Bueno, adiós entonces.",
  ["data.otservbr.global.npc.thorwulf.L223.907"] = "Hola |PLAYERNAME|.",
  ["data.otservbr.global.npc.thorwulf.L224.908"] = "Adiós |PLAYERNAME|.",
  ["data.otservbr.global.npc.thorwulf.L225.909"] = "Chao.",
  ["data.otservbr.global.npc.tibra.L137.512"] = "¡Bienvenido en nombre de los dioses, peregrino |PLAYERNAME|!",
  ["data.otservbr.global.npc.tibra.L138.513"] = "Adiós, |PLAYERNAME|. ¡Que los dioses estén contigo para protegerte y guiarte, hija mía!",
  ["data.otservbr.global.npc.tigo.L59.857"] = "[EN] There, there initiate. You will now become one of us, as so many before you. One of the {Barkless}. Walk with us and you will walk tall my friend.",
  ["data.otservbr.global.npc.tigo.L96.858"] = "Bueno, adiós entonces.",
  ["data.otservbr.global.npc.tim.the.guard.L93.608"] = "¡VIVA EL REY!",
  ["data.otservbr.global.npc.tim.the.guard.L94.609"] = "¡VIVA EL REY!",
  ["data.otservbr.global.npc.tim.the.guard.L95.610"] = "¡VIVA EL REY!",
  ["data.otservbr.global.npc.timothy.L82.683"] = "¡Hola! Es un placer recibir a un visitante del continente.",
  ["data.otservbr.global.npc.timur.L60.1070"] = "¡Bienvenido a mi pequeña tienda, aventurero! Primero lee mis pizarrones.",
  ["data.otservbr.global.npc.timur.L61.1071"] = "Bye, bye.",
  ["data.otservbr.global.npc.timur.L62.1072"] = "Bye, bye.",
  ["data.otservbr.global.npc.todd.L83.450"] = "[EN] Uhm oh hello |PLAYERNAME|... not so loud please... my {head}... What ... do you {want}?",
  ["data.otservbr.global.npc.todd.L84.451"] = "Sí, adiós |PLAYERNAME|, déjame en paz.",
  ["data.otservbr.global.npc.todd.L85.452"] = "Silencio al fin.",
  ["data.otservbr.global.npc.tom.L264.1441"] = "¿Oh?",
  ["data.otservbr.global.npc.tom.L265.1442"] = "Claro, revisa lo que compro.",
  ["data.otservbr.global.npc.tom.L66.1435"] = "[EN] Hey there, |PLAYERNAME|. Did Vascalir send you to me for a {mission}?",
  ["data.otservbr.global.npc.tom.L69.1436"] = "Ahora, ahora... no podemos trabajar con eso. ¡Vuelve a esa guarida de lobos y cumple tu misión! A menos que haya algo más en lo que pueda ayudarte.",
  ["data.otservbr.global.npc.tom.L72.1437"] = "Hola, |PLAYERNAME|. Te ves... exhausto. ¿Corriste mucho? Y lo que es más importante, ¿pudiste encontrar cuero de lobo de guerra?",
  ["data.otservbr.global.npc.tom.L74.1438"] = "Hola, |PLAYERNAME|. Soy Tom el curtidor. Si tienes {corpses}, cuero, patas u otras partes del cuerpo de animales frescos, {trade} conmigo.",
  ["data.otservbr.global.npc.tom.L84.1439"] = "Buena caza, niña.",
  ["data.otservbr.global.npc.tom.L86.1440"] = "Buena caza, hijo.",
  ["data.otservbr.global.npc.tomruk.the.ruddy.L126.1287"] = "Hola hola! ¡Siempre es bueno ver sangre fresca! ¿Qué te trae por aquí?",
  ["data.otservbr.global.npc.tonar.L72.1207"] = "Bienvenido, Señor.",
  ["data.otservbr.global.npc.tonar.oskayaat.L72.1247"] = "Bienvenido atrás, Señor.",
  ["data.otservbr.global.npc.topsy.L181.925"] = "Por supuesto, simplemente navega por mis productos. ¿O quieres mirar sólo",
  ["data.otservbr.global.npc.topsy.L182.926"] = "Adiós, |PLAYERNAME|. ¡Ven de nuevo!",
  ["data.otservbr.global.npc.topsy.L183.927"] = "Adiós, |PLAYERNAME|. ¡Ven de nuevo!",
  ["data.otservbr.global.npc.torkada.L96.1008"] = "¡Saludos! Sin embargo, este no es el {time} para charlar.",
  ["data.otservbr.global.npc.torkada.L97.1009"] = "Chao.",
  ["data.otservbr.global.npc.torkada.L98.1010"] = "Adiós, |PLAYERNAME|.",
  ["data.otservbr.global.npc.trisha.L104.108"] = "¡Bienvenido de nuevo, caballero |PLAYERNAME|!",
  ["data.otservbr.global.npc.trisha.L234.109"] = "Tenga cuidado en sus viajes.",
  ["data.otservbr.global.npc.trisha.L235.110"] = "No te hagas daño con esa arma, pequeña.",
  ["data.otservbr.global.npc.turvy.L58.372"] = "Hola querido |PLAYERNAME|. ¿Puedo ser de alguna ayuda? Sólo dime si te gustaría {trade} armas o armaduras.",
  ["data.otservbr.global.npc.turvy.L59.373"] = "Adiós, |PLAYERNAME|. ¡Vuelve otra vez!.",
  ["data.otservbr.global.npc.turvy.L60.374"] = "Adiós, |PLAYERNAME|. ¡Vuelve otra vez!.",
  ["data.otservbr.global.npc.turvy.L61.375"] = "Por supuesto, simplemente navega por mis ofertas.",
  ["data.otservbr.global.npc.tyrias.L173.1272"] = "¡Bienvenido, joven |PLAYERNAME|! Si estás gravemente herido o envenenado, puedo {heal} gratis.",
  ["data.otservbr.global.npc.tyrias.L174.1273"] = "Recuerda: si estás gravemente herido o envenenado, puedo curarte gratis.",
  ["data.otservbr.global.npc.tyrias.L175.1274"] = "¡Que los dioses te bendigan, |PLAYERNAME|!",
  ["data.otservbr.global.npc.ubaid.L175.124"] = "¡Adiós humano!",
  ["data.otservbr.global.npc.ubaid.L176.125"] = "¡Adiós humano!",
  ["data.otservbr.global.npc.ukea.L57.1102"] = "¡Adiós!",
  ["data.otservbr.global.npc.ulala.L136.675"] = "Los espíritus te dan la bienvenida.",
  ["data.otservbr.global.npc.umar.L162.1233"] = "<salutes>Aaaa -¡atención!",
  ["data.otservbr.global.npc.umar.L163.1234"] = "<salutes>Aaaa -¡atención!",
  ["data.otservbr.global.npc.undal.L167.1466"] = "Saludos héroe. Supongo que viniste a {talk}.",
  ["data.otservbr.global.npc.undal.L168.1467"] = "Bueno, adiós entonces.",
  ["data.otservbr.global.npc.undal.L169.1468"] = "Bueno, adiós entonces.",
  ["data.otservbr.global.npc.urks.the.mute.L73.1084"] = "¡Bienvenido, |PLAYERNAME|! Precioso barco de vapor, ¿no? Incluso puedo ofrecerte un {passage} si quieres.",
  ["data.otservbr.global.npc.urks.the.mute.L74.1085"] = "Hasta la próxima.",
  ["data.otservbr.global.npc.urks.the.mute.L75.1086"] = "Hasta la próxima.",
  ["data.otservbr.global.npc.ustan.L91.1076"] = "La bendición de Crunor, viajero.",
  ["data.otservbr.global.npc.uzgod.L146.1355"] = "¡Hola |PLAYERNAME|! ¿Quieres arma, eh?",
  ["data.otservbr.global.npc.uzgod.L147.1356"] = "Adiós. Volviendo pronto.",
  ["data.otservbr.global.npc.uzgod.L148.1357"] = "Adiós. Volviendo pronto.",
  ["data.otservbr.global.npc.uzon.L115.987"] = "[EN] Daraman's blessings, traveller |PLAYERNAME|.",
  ["data.otservbr.global.npc.uzon.L116.988"] = "Las bendiciones de Daraman",
  ["data.otservbr.global.npc.uzon.L117.989"] = "Las bendiciones de Daraman",
  ["data.otservbr.global.npc.uzon.back.L80.47"] = "[EN] Daraman's blessings, traveller |PLAYERNAME|.",
  ["data.otservbr.global.npc.uzon.back.L81.48"] = "Las bendiciones de Daraman",
  ["data.otservbr.global.npc.uzon.back.L82.49"] = "Las bendiciones de Daraman",
  ["data.otservbr.global.npc.valentina.L83.544"] = "Bienvenido a la tienda de San Valentín. ¿Vamos a {trade} algo?",
  ["data.otservbr.global.npc.valentina.L84.545"] = "Por favor regresa de vez en cuando.",
  ["data.otservbr.global.npc.valentina.L85.546"] = "Por favor regresa de vez en cuando.",
  ["data.otservbr.global.npc.valindara.L66.1597"] = "Saludos, comienzo mortal.",
  ["data.otservbr.global.npc.valindara.L67.1598"] = "Sí, tengo algunas pociones y runas si estás interesado. ¿O quieres comprar solo pociones o solo runas? Oh, si quieres vender o comprar gemas, también puedes preguntarme.",
  ["data.otservbr.global.npc.valindara.L68.1599"] = "Que la iluminación sea tu camino, |PLAYERNAME|.",
  ["data.otservbr.global.npc.vanys.L167.531"] = "Saludos héroe. Supongo que viniste a {talk}.",
  ["data.otservbr.global.npc.vanys.L168.532"] = "Bueno, adiós entonces.",
  ["data.otservbr.global.npc.vanys.L169.533"] = "Bueno, adiós entonces.",
  ["data.otservbr.global.npc.vascalir.L100.1525"] = "Bienvenido de nuevo, |PLAYERNAME|. Me alegra ver que regresaste de una pieza. Espero que no estés demasiado agotado, porque podría usar tu {help} nuevamente.",
  ["data.otservbr.global.npc.vascalir.L103.1526"] = "¡Hola |PLAYERNAME|! ¿Has decidido colarte en la guarida de la tarántula y recuperar una muestra de su red? ¿Estás dispuesto a ello?",
  ["data.otservbr.global.npc.vascalir.L106.1527"] = "¿Necesitas nuevamente las instrucciones para la guarida de la tarántula?",
  ["data.otservbr.global.npc.vascalir.L109.1528"] = "¡Ah, bien hecho! Déjame tomarte esa muestra de telaraña. Cuidado, cuidado... es resistente, pero frágil. ¡Gracias! Debería poder hacer una gran trampa paralizante con ésta. Toma, también tengo algo resistente para ti. ¿Lo quieres?",
  ["data.otservbr.global.npc.vascalir.L114.1529"] = "¡Bienvenido de nuevo, |PLAYERNAME|! ¿Qué tal esa armadura con tachuelas? ¿Te gustaría tenerla ahora?",
  ["data.otservbr.global.npc.vascalir.L121.1530"] = "|PLAYERNAME|! ¡Gracias a los dioses que has vuelto! Mientras no estabas, sucedió algo horrible. ¿Hueles el fuego?",
  ["data.otservbr.global.npc.vascalir.L128.1531"] = "Dios mío, ¿qué pasó con tu cabello? Tu cara también está toda negra; debe haber un infierno de llamas allí abajo. Eso es muy valiente de tu parte. ¿Recibiste el libro?",
  ["data.otservbr.global.npc.vascalir.L131.1532"] = "¿Estás preparado para tu próxima misión, |PLAYERNAME|?",
  ["data.otservbr.global.npc.vascalir.L138.1533"] = "Ahora que sabes cómo almacenar tu dinero, es hora de perseguir a los trolls. Incluso te daré más equipo como recompensa. ¿Te sientes preparado para esa misión?",
  ["data.otservbr.global.npc.vascalir.L145.1534"] = "|PLAYERNAME|, ¡bienvenido de nuevo! Fue un gran trabajo el que hiciste allí. Déjame darte algo por tus esfuerzos: te lo mereces. Toma, ¿quieres un casco?",
  ["data.otservbr.global.npc.vascalir.L150.1535"] = "Saludos, |PLAYERNAME|. ¿Tienes suficiente espacio ahora para el casco de latón?",
  ["data.otservbr.global.npc.vascalir.L153.1536"] = "Saludos, |PLAYERNAME|. ¿Estás listo para tu próxima misión?",
  ["data.otservbr.global.npc.vascalir.L156.1537"] = "Saludos, |PLAYERNAME|. Veo que aún no has explorado toda la cripta. ¿Necesitas explicaciones otra vez?",
  ["data.otservbr.global.npc.vascalir.L159.1538"] = "¡Bienvenido de nuevo, |PLAYERNAME|! ¿Encontraste un bonito hueso carnoso en la cripta?",
  ["data.otservbr.global.npc.vascalir.L162.1539"] = "¡Bienvenido de nuevo, |PLAYERNAME|! ¿Tienes suficiente espacio para esa espada ahora?",
  ["data.otservbr.global.npc.vascalir.L165.1540"] = "¡Saludos, |PLAYERNAME|! Estoy de muy buen humor, debo decir. Casi podemos infiltrarnos en el escondite de Kraknaknork. Tengo un último pequeño favor que pedir y entonces mi plan estará completo. ¿Estás listo?",
  ["data.otservbr.global.npc.vascalir.L168.1541"] = "¡Bienvenido de nuevo, |PLAYERNAME|! Pero... ¿volverás tan pronto? Encuentra la guarida de las avispas en la región noroeste de Rookgaard y usa el frasco que te di en su cadáver. ¿O perdiste el matraz?",
  ["data.otservbr.global.npc.vascalir.L171.1542"] = "¡Bienvenido de nuevo, |PLAYERNAME|! ¿Pudiste traer algo de veneno para avispas?",
  ["data.otservbr.global.npc.vascalir.L174.1543"] = "¡Bienvenido de nuevo, |PLAYERNAME|! ¿Tienes suficiente espacio para ese escudo de latón ahora?",
  ["data.otservbr.global.npc.vascalir.L177.1544"] = "|PLAYERNAME|, ha llegado el momento de nuestro triunfo. ¿Estás listo para vencer a Kraknaknork de una vez por todas?",
  ["data.otservbr.global.npc.vascalir.L184.1545"] = "|PLAYERNAME|! ¡Has vuelto! Y estás cubierto de sangre de orco... eso sólo puede significar... ¿fuiste capaz de matar a Kraknaknork?",
  ["data.otservbr.global.npc.vascalir.L81.1520"] = "Bienvenido, aventurero |PLAYERNAME|. Son tiempos terribles para Rookgaard... ¿has venido a ayudar en nuestro {mission}?",
  ["data.otservbr.global.npc.vascalir.L84.1521"] = "Saludos, |PLAYERNAME|. Tu tarea aún no ha terminado. ¿Recuerdas todo lo que debes hacer?",
  ["data.otservbr.global.npc.vascalir.L87.1522"] = "Saludos, |PLAYERNAME|. Escuché un fuerte estruendo desde el techo. Espero que las piedras no te hayan caído sobre los dedos de los pies. ¿Has cargado al menos dos catapultas?",
  ["data.otservbr.global.npc.vascalir.L90.1523"] = "Saludos, |PLAYERNAME|. En realidad tengo más equipo que podría darte, pero primero quiero ver cómo peleas. Has peleado antes, ¿no?",
  ["data.otservbr.global.npc.vascalir.L93.1524"] = "Bienvenido de nuevo, |PLAYERNAME|. ¿Terminaste con las 5 ratas que te pedí que mataras?",
  ["data.otservbr.global.npc.vascalir.L938.1546"] = "Despedida.",
  ["data.otservbr.global.npc.vascalir.L939.1547"] = "Despedida.",
  ["data.otservbr.global.npc.vescu.L103.84"] = "Oye, pareces alguien que disfruta de un buen {booze}.",
  ["data.otservbr.global.npc.vescu.L196.85"] = "Es hora de otra b-cerveza. <palejones>",
  ["data.otservbr.global.npc.vescu.L197.86"] = "Oh, dos trolls. Hola, pequeños dos. <palejones>",
  ["data.otservbr.global.npc.virgil.L76.212"] = "¿Sí? ¿Qué puedo hacer por ti, |PLAYERNAME|? ¿Negocios bancarios, tal vez?",
  ["data.otservbr.global.npc.virgil.L77.213"] = "Que tenga un lindo día.",
  ["data.otservbr.global.npc.virgil.L78.214"] = "Que tenga un lindo día.",
  ["data.otservbr.global.npc.walter.jaeger.L294.1181"] = "Asegúrate de tener espacios libres en la bandeja de entrada de tu tienda.",
  ["data.otservbr.global.npc.walter.jaeger.L485.1182"] = "¡Buena caza! ¡Puedo ofrecerte unos encantadores {rewards} para terminar las tareas de caza de presas! Además, puedo decirte cuántos puntos de tareas de caza (HTP) tienes realmente {have} y ya tienes {spent}.",
  ["data.otservbr.global.npc.walter.jaeger.L486.1183"] = "¡Sigue cazando!",
  ["data.otservbr.global.npc.walter.jaeger.L487.1184"] = "¡Sigue cazando!",
  ["data.otservbr.global.npc.walter.the.guard.L88.164"] = "¡VIVA EL REY!",
  ["data.otservbr.global.npc.wentworth.L387.330"] = "¿Sí? ¿Qué puedo hacer por ti, |PLAYERNAME|? ¿Negocios bancarios, tal vez?",
  ["data.otservbr.global.npc.wentworth.L388.331"] = "Que tenga un lindo día.",
  ["data.otservbr.global.npc.wentworth.L389.332"] = "Que tenga un lindo día.",
  ["data.otservbr.global.npc.willard.L86.1037"] = "¡Saludos y Banor esté contigo, |PLAYERNAME|! ¿Puedo interesarle un {trade} para armas, municiones o armaduras?",
  ["data.otservbr.global.npc.willard.L87.1038"] = "Adiós, |PLAYERNAME|.",
  ["data.otservbr.global.npc.willard.L88.1039"] = "Adiós, |PLAYERNAME|.",
  ["data.otservbr.global.npc.willard.L89.1040"] = "Por supuesto, simplemente navega por mis productos. Si solo está interesado en el equipo {distance}, hágamelo saber.",
  ["data.otservbr.global.npc.willie.L283.1021"] = "¡Sí, vete!",
  ["data.otservbr.global.npc.willie.L284.1022"] = "Sí, adiós |PLAYERNAME|.",
  ["data.otservbr.global.npc.willie.L285.1023"] = "Echa un buen vistazo.",
  ["data.otservbr.global.npc.willie.L286.1024"] = "[EN] Hiho |PLAYERNAME|. I hope you're here to {trade}.",
  ["data.otservbr.global.npc.woblin.L115.869"] = "¡Hola humano!",
  ["data.otservbr.global.npc.wyda.L132.1254"] = "¿Qué? ¿Un mundano hablándome? Divertido.",
  ["data.otservbr.global.npc.wyrdin.L154.1122"] = "Hola, ¿qué te trae por aquí?",
  ["data.otservbr.global.npc.wyrdin.L155.1123"] = "Buena suerte en tus viajes, |PLAYERNAME|.",
  ["data.otservbr.global.npc.xelvar.L124.850"] = "Saludos. ¿Estás interesado en las aventuras?",
  ["data.otservbr.global.npc.xodet.L175.345"] = "Por supuesto, simplemente navega por mis productos. ¿O quieres mirar sólo",
  ["data.otservbr.global.npc.xodet.L176.346"] = "Adiós y vuelve otra vez.",
  ["data.otservbr.global.npc.xodet.L177.347"] = "Adiós y vuelve otra vez.",
  ["data.otservbr.global.npc.xorlosh.L91.605"] = "Nos vemos amigo.",
  ["data.otservbr.global.npc.xorlosh.L92.606"] = "Nos vemos amigo.",
  ["data.otservbr.global.npc.xorlosh.L93.607"] = "¿Quién eres? ¿Eres un genio en mecánica? No lo pareces.",
  ["data.otservbr.global.npc.yaman.L167.634"] = "Adiós, humano.",
  ["data.otservbr.global.npc.yaman.L168.635"] = "Adiós, humano.",
  ["data.otservbr.global.npc.yaman.L169.636"] = "A su servicio, simplemente explore mis productos.",
  ["data.otservbr.global.npc.yasir.L830.924"] = "[EN] Si, jema ze harun. <waves>",
  ["data.otservbr.global.npc.yberius.L169.1364"] = "¡Bienvenido, joven |PLAYERNAME|! Si estás gravemente herido o envenenado, puedo {heal} gratis.",
  ["data.otservbr.global.npc.yberius.L170.1365"] = "Recuerda: si estás gravemente herido o envenenado, puedo curarte gratis.",
  ["data.otservbr.global.npc.yberius.L171.1366"] = "¡Que los dioses te bendigan, |PLAYERNAME|!",
  ["data.otservbr.global.npc.yoem.L61.188"] = "¡Hola |PLAYERNAME|! ¿Necesitas algún equipamiento para tu casa?",
  ["data.otservbr.global.npc.yoem.L62.189"] = "Échale un vistazo. La mayoría de los muebles vienen en prácticos kits. Utilízalos en tu casa para montar los muebles. ¿Quieres ver sólo un determinado {type} de muebles?",
  ["data.otservbr.global.npc.yonan.L137.684"] = "¿Cómo podría ayudarte?",
  ["data.otservbr.global.npc.yonan.L140.685"] = "¿Cómo podría ayudarte?",
  ["data.otservbr.global.npc.yonan.L143.686"] = "¿Cómo podría ayudarte?",
  ["data.otservbr.global.npc.yonan.L216.687"] = "Bueno, adiós entonces.",
  ["data.otservbr.global.npc.zalamon.L421.1289"] = "No hay muchos viajeroszz zzezze dayzz. Espero que traigas buenas noticias.",
  ["data.otservbr.global.npc.zarifan.L89.1262"] = "... ... hola... ¿palabras... mágicas?",
  ["data.otservbr.global.npc.zebron.L134.469"] = "Saludos, gran apostador. ¿Entonces te interesa un juego, |PLAYERNAME|?",
  ["data.otservbr.global.npc.zebron.L135.470"] = "Oye, no puedes irte. La suerte te sonríe. ¡Puedo sentirlo!",
  ["data.otservbr.global.npc.zebron.L136.471"] = "Oye, no puedes irte, |PLAYERNAME|. La suerte te sonríe. ¡Puedo sentirlo!",
  ["data.otservbr.global.npc.zedrulon.the.fallen.L148.50"] = "¡Bienvenido, joven |PLAYERNAME|! Si estás gravemente herido o envenenado, puedo {heal} gratis.",
  ["data.otservbr.global.npc.zedrulon.the.fallen.L149.51"] = "Recuerda: si estás gravemente herido o envenenado, puedo curarte gratis.",
  ["data.otservbr.global.npc.zedrulon.the.fallen.L150.52"] = "¡Que los dioses te bendigan, |PLAYERNAME|!",
  ["data.otservbr.global.npc.zerbrus.L210.7"] = "Hm.",
  ["data.otservbr.global.npc.zirella.L180.497"] = "[EN] Good bye |PLAYERNAME|, may Uman bless you!.",
  ["data.otservbr.global.npc.zirella.L181.498"] = "Adiós viajero, cuídate.",
  ["data.otservbr.global.npc.zirella.L67.488"] = "¡Oh, el cielo debe haberte enviado! ¿Podrías ayudarme con un {quest}?",
  ["data.otservbr.global.npc.zirella.L70.489"] = "Bienvenido de nuevo, cariño... en cuanto a esa leña, ¿podrías por favor {help}?",
  ["data.otservbr.global.npc.zirella.L73.490"] = "Bienvenido de nuevo, cariño... entonces, sobre el {dead trees}, déjame explicarte un poco más, ¿{yes}?",
  ["data.otservbr.global.npc.zirella.L76.491"] = "Bienvenido de nuevo, cariño... entonces, sobre el {branches}, déjame explicarte un poco más, ¿{yes}?",
  ["data.otservbr.global.npc.zirella.L79.492"] = "Bienvenido de nuevo, cariño... entonces, sobre el {pushing}, déjame explicarte un poco más, ¿{yes}?",
  ["data.otservbr.global.npc.zirella.L82.493"] = "Bienvenido de nuevo, cariño... entonces, sobre el {cart}, déjame explicarte un poco más, ¿{yes}?",
  ["data.otservbr.global.npc.zirella.L85.494"] = "Oh, cariño, ¿hay algún problema con la misión? ¿Debería {explain} volver a hacerlo?",
  ["data.otservbr.global.npc.zirella.L88.495"] = "¡Bien, gracias cariño! Esto será suficiente para calentar mi horno. Ah, y probablemente estés esperando tu recompensa, ¿{yes}?",
  ["data.otservbr.global.npc.zirella.L91.496"] = "¡Bienvenida de nuevo, querida Isleth Eagonst! ¿Estás aquí para charlar un poco? Simplemente use el {keywords} resaltado nuevamente para elegir un {topic}.",
  ["data.otservbr.global.npc.ziyad.L100.872"] = "Ah, el viento trae otro visitante. Bienvenido, querido invitado. ¿Estás buscando un {passage} con mi alfombra?",
  ["data.otservbr.global.npc.ziyad.L101.873"] = "Adiós. Recomiéndenos si quedó satisfecho con nuestro servicio.",
  ["data.otservbr.global.npc.ziyad.L102.874"] = "Bueno, adiós entonces.",
  ["data.otservbr.global.npc.zizzle.L114.1235"] = "[EN] Ah our human {alliez} have finally arrived! I've already feared zat ze emperor'z forzez had caught you. Your rezilienze and prowezz are imprezzive.",
  ["data.otservbr.global.npc.zlak.L103.716"] = "Déjame en paz.",
  ["data.otservbr.global.npc.znozel.L71.200"] = "¿Sí? ¿Qué puedo hacer por ti, |PLAYERNAME|? ¿Negocios bancarios, tal vez?",
  ["data.otservbr.global.npc.znozel.L72.201"] = "Que tenga un lindo día.",
  ["data.otservbr.global.npc.znozel.L73.202"] = "Que tenga un lindo día.",
  ["data.otservbr.global.npc.zoltan.L113.593"] = "Bienvenido |PLAYERNAME|, estudiante de las artes arcanas. Enseño el {spells} más feroz disponible.",
  ["data.otservbr.global.npc.zoltan.L114.594"] = "Utilice sus conocimientos sabiamente, |PLAYERNAME|.",
  ["data.otservbr.global.npc.zora.L82.1328"] = "Oh, por favor entra, |PLAYERNAME|. ¿Qué puedo hacer por ti? Si necesitas equipo de aventura, pídeme un {trade}.",
  ["data.otservbr.global.npc.zora.L83.1329"] = "Adiós, |PLAYERNAME|.",
  ["data.otservbr.global.npc.zora.L84.1330"] = "Adiós, |PLAYERNAME|.",
  ["data.otservbr.global.npc.zora.L85.1331"] = "Por supuesto, simplemente navega por mis productos. {Footballs} debe comprarse por separado.",
  ["data.otservbr.global.npc.ztiss.L98.98"] = "Sea saludado mi.. {guezt}.",
  ["data.otservbr.global.npc.zumtah.L141.1448"] = "Otro visitante de este reino restringido, acogedor y tranquilo, perfecto excepto por un {exit}. Mujaja.",
  ["data.otservbr.global.npc.zumtah.L142.1449"] = "Mujajaja.",
