  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.analyser.L20.2105"] = "¡Bien hecho! El agua está analizada.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.counter.agent.L37.2085"] = "Una tormenta de arena ha destruido casi todos los pilares. El efecto del contraagente funcionó diferente de lo esperado.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.counter.agent.L38.2086"] = "La tormenta de arena no solo ha destruido el oasis, también reveló algunas baldosas y una palanca.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.crate.L11.2083"] = "Ya tomaste el magnificador.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.crate.L13.2084"] = "Esta caja pertenece a Angelo. Deberías hablar con él antes de sacar algo.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.crate.L7.2082"] = "¡Perfecto! Tomaste una lupa maravillosa de esta caja.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.document.L10.2103"] = "Entonces, por una pequeña asignación para gastos, la recuperarás. Simplemente habla con Iwar en Kazordoon para obtener más información.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.document.L11.2104"] = "Pregúntale: ¿Te ha comido la lengua el gato?",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.document.L7.2100"] = "Querido curador, este museo recientemente abierto es un lugar realmente agradable.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.document.L8.2101"] = "¡Pero espera! ¿Qué hay del espacio vacío frente a ti? ¡Qué lástima!",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.document.L9.2102"] = "Parece que alguien ha quitado una de las hermosas pinturas. ¡Pero vamos! Tú tienes el dinero y nosotros lo necesitamos.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.last.object.L23.2096"] = "El extraño símbolo en la pared del fondo brilla violentamente.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.last.object.L24.2097"] = "El objeto de culto simplemente yace ahí tranquilamente. El área peligrosa a su alrededor se ha disuelto casi por completo.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.last.object.L25.2098"] = "Al extender la mano para tocar el objeto de culto, una oleada de energía estalla del cráneo. Desterraste su poder.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.magnifier.L19.2122"] = "Nada especial. Esta imagen parece genuina.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.magnifier.L24.2123"] = "¡Esta es! ¡Parece que fue pintada por un niño!",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.misguided.L62.2109"] = "Paralizas al matón y el amuleto revela la verdadera cara de la criatura detrás de la posesión de esta criatura desviada.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.torch.L18.2116"] = "Oyes un fuerte sonido de trituración no muy lejos de ti. Algo muy pesado parece haberse movido.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.movements.begin.task.L36.2106"] = "El amuleto quema tu piel. Tiene hambre de energía ahora mismo, reúne una gran cantidad de energía lo más rápido posible para cargarlo.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.movements.check.oasis.L10.2108"] = "Has encontrado un encantador oasis con fauna verde y fruta jugosa. No te lo esperabas.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.movements.energy.fence.L31.2117"] = "Siendo tú el recipiente que une el poder de las almas marchitas, pasas a través de la barrera mágica.",
