  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L232.1707"] = "Te ves casi como un orco. No engañará a todos los orcos, pero el guardia estúpido frente a la fortaleza debería caer.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L277.1708"] = "¡Esto debería ser suficiente distracción para que te cueles en la fortaleza! ¡Date prisa!",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L310.1709"] = "Has envenenado la sopa de Kraknaknork. Esto debería debilitarlo inmensamente. Es hora de encontrar su habitación.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L329.1710"] = "¡El berserker ya no puede atraparte - pero solo durante 20 segundos! ¡Necesitas alejarlo del teletransportador!",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L362.1711"] = "Mientras el berserker orco esté cerca de ese teletransportador, no puedes entrar.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L370.1712"] = "Estás entrando a la guarida de Kraknaknork.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L483.1713"] = "Una barrera de energía en algún lugar desapareció temporalmente.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L516.1714"] = "Con su última energía, Kraknaknork te empuja fuera de su sala del trono. Date prisa en volver y derrótalo antes de que recupere su poder.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L549.1715"] = "Un jugador ya está dentro de la sala del jefe.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L564.1716"] = "Estás entrando a la sala del trono de Kraknaknork. ¡Tienes 5 minutos para matarlo!",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L595.1717"] = "Te retiraste de la pelea. Puedes intentarlo de nuevo cuando quieras.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L624.1718"] = "Aún no puedes usar este teletransportador.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L684.1719"] = "Has encontrado",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L686.1720"] = "Has encontrado",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L691.1721"] = "The",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L717.1722"] = "Con la última fuente de energía de Kraknaknork, escapas de la fortaleza. Es hora de volver con Vascalir.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L776.1723"] = "Has encontrado",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L778.1724"] = "Has encontrado",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L783.1725"] = "The",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.bursting.at.the.seams.museum.actions.doors.L18.2291"] = "La puerta parece estar sellada contra intrusos no deseados.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.high.and.dry.isles.actions.telescope.L6.2318"] = "El telescopio ofrece una vista perfecta del océano sin fin - no se ve tierra a la vista",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.high.and.dry.isles.movements.boat.puzzle.L13.2312"] = "Ves las partes dispersas de un barco naufragado. Milagrosamente el telescopio del barco sobrevivió al naufragio, parece estar intacto aún.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.high.and.dry.isles.movements.boat.puzzle.L16.2313"] = "Todavía hay algunas tablas sueltas y cabos. No puedes usar la balsa así, seguro se hundirá.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.high.and.dry.isles.movements.boat.puzzle.L21.2314"] = "Usas el cabo para atar las tablas sueltas. La balsa debería estar lista para navegar ahora.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.high.and.dry.isles.movements.boat.puzzle.L27.2315"] = "Ves las partes dispersas de un barco naufragado. Milagrosamente el telescopio del barco sobrevivió al naufragio, parece estar intacto aún.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.high.and.dry.isles.movements.boat.puzzle.L30.2316"] = "Sin puntos de orientación nunca encontrarás el camino de vuelta. Intenta encontrar una forma de mejorar tu navegación.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.high.and.dry.isles.movements.stepIn.L91.2317"] = "Debes esperar. Alguien está desafiando a",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.library.area.movements.mazzinor.L13.2290"] = "Los restos te despolarizan temporalmente.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.the.lament.asuras.actions.bonefiddle.L16.2302"] = "Clavas el cabello al diapasón de ébano. Los mechones deberían ser adecuados para servir como cuerdas.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.the.lament.asuras.actions.bonefiddle.L27.2303"] = "*Hubo una vez una doncella hermosa, con ojos oscuros y cabello sedoso. Lejos de casa murió. Sin tumba, sin velorio, sin duelo.*",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.the.lament.asuras.actions.bonefiddle.L31.2304"] = "Estás tocando la Balada del Pavo Real y el portal se abre.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.the.lament.asuras.actions.bonefiddle.L37.2305"] = "Estás tocando el violín de hueso.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.the.lament.asuras.actions.bonefiddle.L9.2301"] = "Adjuntas la madera de ébano al cráneo. Esto debería cumplir los requisitos de un diapasón.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.the.lament.asuras.actions.doors.L16.2310"] = "Solo los dignos pueden pasar.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.the.lament.asuras.actions.doors.L19.2311"] = "La puerta parece estar sellada contra intrusos no deseados.",
